CREATE TABLE IF NOT EXISTS time_slots(id INT PRIMARY KEY, weekday VARCHAR(12) NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,UNIQUE(weekday,start_time));
CREATE TABLE IF NOT EXISTS authors(id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(140) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS book_authors(book INT NOT NULL,author INT NOT NULL, PRIMARY KEY(book,author),FOREIGN KEY(book) REFERENCES books(id), FOREIGN KEY(author) REFERENCES authors(id));
CREATE TABLE IF NOT EXISTS invoice_details(invoice INT PRIMARY KEY,term INT,issued DATE NOT NULL,FOREIGN KEY(invoice) REFERENCES invoices(id),FOREIGN KEY(term) REFERENCES semesters(id));
CREATE TABLE IF NOT EXISTS registration_events(id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reg INT NOT NULL,actor INT NOT NULL,state VARCHAR(20) NOT NULL,comment_text VARCHAR(140),created TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(reg) REFERENCES registrations(id),FOREIGN KEY(actor) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS thesis_events(id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,thesis INT NOT NULL,actor INT NOT NULL,state VARCHAR(30) NOT NULL,note VARCHAR(140),created TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(thesis) REFERENCES theses(id),FOREIGN KEY(actor) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS routine_conflicts(id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,term INT NOT NULL,actor INT NOT NULL,reason VARCHAR(250) NOT NULL,created TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(term) REFERENCES semesters(id),FOREIGN KEY(actor) REFERENCES users(id));
CREATE OR REPLACE VIEW course_offerings AS SELECT course,term,COUNT(*) section_count FROM offerings GROUP BY course,term;
CREATE OR REPLACE VIEW academic_sections AS SELECT o.*,COALESCE(d.status,'Active') availability FROM offerings o LEFT JOIN section_details d ON d.offering=o.id;
CREATE OR REPLACE VIEW user_roles AS SELECT id user_id,role role_name FROM users;
CREATE OR REPLACE VIEW roles AS SELECT DISTINCT role_name FROM role_permissions;
CREATE OR REPLACE VIEW permissions AS SELECT DISTINCT permission_name FROM role_permissions;
CREATE OR REPLACE VIEW payments AS SELECT r.*,COALESCE(d.state,'Valid') state,d.method,d.actor recorded_by FROM receipts r LEFT JOIN receipt_details d ON d.receipt=r.id WHERE r.kind='Payment';
CREATE OR REPLACE VIEW waivers AS SELECT r.*,COALESCE(d.state,'Valid') state,d.reason,d.reviewer approved_by FROM receipts r LEFT JOIN receipt_details d ON d.receipt=r.id WHERE r.kind='Waiver';
